  "audius_id"              text    NOT NULL,
  "track_cid"              text,
  "audius_user_id"         text,
  "audius_permalink"       text,
  "audius_license"         text,
  "audius_license_url"     text,
  "audius_mood"            text,
  "audius_tags"            jsonb,
  "audius_play_count"      bigint,
  "audius_repost_count"    bigint,
  "audius_favorite_count"  bigint,
  "audius_comment_count"   bigint,
  "audius_is_downloadable" boolean,
  CONSTRAINT "audius_song_data_audius_id_key" UNIQUE (audius_id),
  CONSTRAINT "audius_song_data_pkey" PRIMARY KEY (song_id),
  CONSTRAINT "audius_song_data_track_cid_key" UNIQUE (track_cid)
);

ALTER TABLE "public"."audius_song_data"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."jamendo_song_data" (
  "song_id"      bigint NOT NULL,
  "jamendo_id"   bigint NOT NULL,
  "audio_url"    text,
  "download_url" text,
  "waveform"     jsonb  DEFAULT '[]'::jsonb,
