ALTER TABLE "public"."jamendo_song_data"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."profile_song_stats" (
  "id"              bigint                   GENERATED BY DEFAULT AS IDENTITY (SEQUENCE NAME "public"."user_song_stats_id_seq") NOT NULL,
  "created_at"      timestamp with time zone NOT NULL DEFAULT now(),
  "song_id"         bigint                   NOT NULL,
  "is_liked"        boolean                  DEFAULT false,
  "play_count"      integer                  DEFAULT 0,
  "skip_count"      integer                  DEFAULT 0,
  "first_played_at" timestamp with time zone DEFAULT (now() AT TIME ZONE 'utc'::text),
  "last_played_at"  timestamp with time zone DEFAULT (now() AT TIME ZONE 'utc'::text),
  "last_skipped_at" timestamp with time zone,
  "total_play_time" integer                  DEFAULT 0,
  "profile_id"      uuid,
  CONSTRAINT "profile_song_stats_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."profile_song_stats"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."profiles" (
  "id"                uuid                     NOT NULL,
  "created_at"        timestamp with time zone NOT NULL DEFAULT now(),
  "genre_preferences" jsonb,
  CONSTRAINT "profiles_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."profiles"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."songs_depricated" (
  "id"              bigint                   GENERATED BY DEFAULT AS IDENTITY (SEQUENCE NAME "public"."songs_id_seq") NOT NULL,
  "created_at"      timestamp with time zone NOT NULL DEFAULT now(),
  "title"           text                     NOT NULL DEFAULT 'Unknown title'::text,
  "artist"          text                     NOT NULL DEFAULT 'Unknown artist'::text,
  "jamendo_id"      bigint,
  "speed"           smallint                 NOT NULL DEFAULT '0'::smallint,
  "provider"        text                     NOT NULL DEFAULT 'jamendo'::text,
  "audio_url"       text,
  "download_url"    text,
  "bpm"             smallint,
  "beat_intervals"  jsonb,
  "bpm_confidence"  smallint,
  "genre"           jsonb,
  "duration"        smallint,
  "waveform"        jsonb                    DEFAULT '[]'::jsonb,
  "shareurl"        text,
  "instruments"     jsonb,
  "vartags"         jsonb,
  "lang"            text,
  "gender"          text,
  "is_instrumental" boolean,
  "is_electric"     boolean,
  "image"           text,
  "start_time"      real                     DEFAULT '0'::real,
  "beat_timestamps" jsonb,
  "release_date"    text,
  "license_ccurl"   text,
  "content_id_free" boolean,
  "license_nc"      boolean,
  "license_sa"      boolean,
  "license_nd"      boolean,
  "license_version" real,
  "end_time"        real                     DEFAULT '0'::real,
  "artist_id"       bigint,
  CONSTRAINT "songs_jamendo_id_key" UNIQUE (jamendo_id),
  CONSTRAINT "songs_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."songs_depricated"
