CREATE TABLE "public"."songs" (
  "id"           bigint                   GENERATED BY DEFAULT AS IDENTITY (SEQUENCE NAME "public"."songs_id_seq1") NOT NULL,
  "created_at"   timestamp with time zone DEFAULT now(),
  "title"        text                     NOT NULL,
  "artist_id"    bigint,
  "bpm"          smallint,
  "duration"     smallint,
  "genre"        text,
  "mood"         text,
  "description"  text,
  "release_date" timestamp with time zone,
  "image"        text,
  "share_url"    text,
  "tags"         jsonb,
  "album_id"     bigint,
  "start_time"   real                     DEFAULT '0'::real,
  "end_time"     real                     DEFAULT '0'::real,
  CONSTRAINT "songs_pkey1" PRIMARY KEY (id)
);

ALTER TABLE "public"."songs"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."workouts" (
  "id"                 bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "created_at"         timestamp with time zone NOT NULL DEFAULT now(),
  "intervals"          jsonb,
  "name"               text                     DEFAULT 'Unnamed Workout'::text,
  "author"             text                     DEFAULT 'Zwift'::text,
  "sport_type_is_bike" boolean                  DEFAULT true,
  "description"        text,
  "tags"               jsonb,
  "chosen_count"       integer                  DEFAULT 0,
  CONSTRAINT "workouts_name_key" UNIQUE (name),
  CONSTRAINT "workouts_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."workouts"
  ENABLE ROW LEVEL SECURITY;

CREATE OR REPLACE FUNCTION public.rls_auto_enable()
  RETURNS event_trigger
  LANGUAGE plpgsql
  SET search_path TO 'pg_catalog'
  AS $function$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$function$;

ALTER TABLE "public"."profiles"
  ADD CONSTRAINT "profiles_id_fkey" FOREIGN KEY (id) REFERENCES auth.users(id) ON DELETE CASCADE;

ALTER TABLE "public"."profile_song_stats"
  ADD CONSTRAINT "profile_song_stats_profile_id_fkey" FOREIGN KEY (profile_id) REFERENCES public.profiles(id) ON UPDATE CASCADE ON DELETE CASCADE;

ALTER TABLE "public"."songs"
  ADD CONSTRAINT "songs_album_id_fkey" FOREIGN KEY (album_id) REFERENCES public.albums(id) ON UPDATE CASCADE ON DELETE CASCADE;

ALTER TABLE "public"."songs"
  ADD CONSTRAINT "songs_artist_id_fkey1" FOREIGN KEY (artist_id) REFERENCES public.artists(id) ON UPDATE CASCADE ON DELETE CASCADE;

ALTER TABLE "public"."audius_song_data"
  ADD CONSTRAINT "audius_song_data_song_id_fkey" FOREIGN KEY (song_id) REFERENCES public.songs(id) ON UPDATE CASCADE ON DELETE CASCADE;

ALTER TABLE "public"."jamendo_song_data"
  ADD CONSTRAINT "jamendo_song_data_song_id_fkey" FOREIGN KEY (song_id) REFERENCES public.songs(id) ON UPDATE CASCADE ON DELETE CASCADE;

ALTER TABLE "public"."profile_song_stats"
  ADD CONSTRAINT "profile_song_stats_song_id_fkey" FOREIGN KEY (song_id) REFERENCES public.songs(id) ON UPDATE CASCADE ON DELETE CASCADE;

CREATE UNIQUE INDEX albums_name_lower_key ON public.albums USING btree (lower(name))
  WHERE (name IS NOT NULL);

CREATE UNIQUE INDEX artists_name_lower_key ON public.artists USING btree (lower(name))
  WHERE (name IS NOT NULL);

CREATE POLICY "Enable read access for all users" ON "public"."albums"
  FOR SELECT
  TO PUBLIC
  USING (true);

CREATE POLICY "Enable read access for all users" ON "public"."artists"
  FOR SELECT
  TO PUBLIC
  USING (true);

CREATE POLICY "Enable read access for all users" ON "public"."audius_song_data"
  FOR SELECT
  TO PUBLIC
  USING (true);

CREATE POLICY "Enable read access for all users" ON "public"."jamendo_song_data"
  FOR SELECT
  TO PUBLIC
  USING (true);

CREATE POLICY "Enable read access for all users [temporary]" ON "public"."profile_song_stats"
  FOR ALL
  TO PUBLIC
  USING (true)
  WITH CHECK (true);

CREATE POLICY "Users can create their own song stats" ON "public"."profile_song_stats"
  FOR INSERT
  TO "authenticated"
  WITH CHECK ((auth.uid() = profile_id));

CREATE POLICY "Users can update their own song stats" ON "public"."profile_song_stats"
  FOR UPDATE
  TO "authenticated"
  USING ((auth.uid() = profile_id))
  WITH CHECK ((auth.uid() = profile_id));

CREATE POLICY "Users can view their own song stats" ON "public"."profile_song_stats"
  FOR SELECT
  TO "authenticated"
  USING ((auth.uid() = profile_id));

CREATE POLICY "Users can create their own profile" ON "public"."profiles"
  FOR INSERT
  TO "authenticated"
  WITH CHECK ((auth.uid() = id));

CREATE POLICY "Users can delete their own profile" ON "public"."profiles"
  FOR DELETE
  TO "authenticated"
  USING ((auth.uid() = id));

CREATE POLICY "Users can update their own profile" ON "public"."profiles"
  FOR UPDATE
  TO "authenticated"
  USING ((auth.uid() = id))
  WITH CHECK ((auth.uid() = id));

CREATE POLICY "Users can view their own profile" ON "public"."profiles"
  FOR SELECT
  TO "authenticated"
  USING ((auth.uid() = id));

CREATE POLICY "Enable read access for all users" ON "public"."songs"
  FOR SELECT
  TO PUBLIC
  USING (true);

CREATE POLICY "Songs are publicly readable" ON "public"."songs_depricated"
  FOR SELECT
  TO "anon"
  USING (true);

CREATE POLICY "Songs are really publicly readable" ON "public"."songs_depricated"
  FOR SELECT
  TO PUBLIC
  USING (true);

CREATE POLICY "Allow all users i hope to view" ON "public"."workouts"
  FOR SELECT
  TO "anon", "authenticated", "authenticator"
  USING (true);

CREATE POLICY "Allow all users to insert" ON "public"."workouts"
  FOR INSERT
  TO "anon", "authenticated"
  WITH CHECK (true);

CREATE POLICY "Authenticated users can update chosen_count" ON "public"."workouts"
  FOR UPDATE
  TO "authenticated"
  USING (true)
  WITH CHECK (true);

CREATE POLICY "Enable read access for all users" ON "public"."workouts"
  FOR SELECT
  TO "anon"
  USING (true);

CREATE EVENT TRIGGER "ensure_rls"
  ON ddl_command_end
  WHEN TAG IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
  EXECUTE FUNCTION "public"."rls_auto_enable"();

COMMENT ON COLUMN "public"."songs_depricated"."duration" IS 'in seconds';

REVOKE ALL ON FUNCTION "public"."rls_auto_enable"() FROM PUBLIC;

GRANT EXECUTE ON FUNCTION "public"."rls_auto_enable"() TO "authenticated", "postgres", "service_role";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."albums" TO "anon", "authenticated", "postgres", "service_role";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."artists" TO "anon", "authenticated", "postgres", "service_role";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."audius_song_data" TO "anon", "authenticated", "postgres", "service_role";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."jamendo_song_data" TO "anon", "authenticated", "postgres", "service_role";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."profile_song_stats" TO "anon", "authenticated", "postgres", "service_role";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."profiles" TO "anon", "authenticated", "postgres", "service_role";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."songs" TO "anon", "authenticated", "postgres", "service_role";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."songs_depricated" TO "anon", "authenticated", "postgres", "service_role";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."workouts" TO "anon";

REVOKE ALL ("chosen_count") ON TABLE "public"."workouts" FROM "authenticated";

GRANT UPDATE ("chosen_count") ON TABLE "public"."workouts" TO "authenticated";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."workouts" TO "authenticated", "postgres", "service_role";

